package interium.fabric;
import com.google.gson.*;import java.io.*;import java.nio.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Opt-in Windows local Discord IPC. No donor ID, DLL, token, username or server address. */
final class DiscordPresence {
 private static volatile long generation;private static volatile RandomAccessFile pipe;private static volatile String status="Отключено";private static Thread worker;private static String app="";private static final long START=System.currentTimeMillis()/1000;
 static String status(){return status;}
 static void tick(){boolean enabled=DeltaVisualSettings.flag("rpc.enabled",false)&&!Boolean.getBoolean("interium.visualSmoke");String id=DeltaVisualSettings.string("rpc.applicationId","").trim();if(!enabled||!id.matches("[0-9]{17,20}")){if(worker!=null)stop();status=enabled?"Нужен свой Application ID":"Отключено";return;}if(!System.getProperty("os.name","").toLowerCase(Locale.ROOT).contains("win")){status="Эта версия IPC поддерживает Windows";return;}if(worker!=null&&worker.isAlive()&&id.equals(app))return;stop();app=id;long gen=++generation;worker=new Thread(()->run(id,gen),"Interium-Discord-IPC");worker.setDaemon(true);worker.start();}
 private static void stop(){generation++;RandomAccessFile p=pipe;pipe=null;if(p!=null)try{p.close();}catch(IOException ignored){}Thread t=worker;worker=null;if(t!=null)t.interrupt();}
 private static void run(String id,long gen){while(gen==generation&&!Thread.currentThread().isInterrupted()){try(RandomAccessFile p=connect()){if(gen!=generation)return;pipe=p;JsonObject hello=new JsonObject();hello.addProperty("v",1);hello.addProperty("client_id",id);send(p,0,hello);read(p);while(gen==generation){JsonObject activity=new JsonObject();activity.addProperty("details","Interium · Minecraft 1.21.11");activity.addProperty("state","Prism / 0.5.7");JsonObject time=new JsonObject();time.addProperty("start",START);activity.add("timestamps",time);JsonObject args=new JsonObject();args.addProperty("pid",ProcessHandle.current().pid());args.add("activity",activity);JsonObject command=new JsonObject();command.addProperty("cmd","SET_ACTIVITY");command.add("args",args);command.addProperty("nonce",UUID.randomUUID().toString());send(p,1,command);JsonObject response=read(p);status=response.has("evt")&&"ERROR".equals(response.get("evt").getAsString())?"Application ID отклонён":"Подключено";Thread.sleep(15000);}}catch(InterruptedException e){Thread.currentThread().interrupt();return;}catch(Exception e){status="Discord недоступен / проверь Application ID";}finally{if(gen==generation)pipe=null;}try{Thread.sleep(30000);}catch(InterruptedException e){Thread.currentThread().interrupt();return;}}}
 private static RandomAccessFile connect()throws IOException{for(int i=0;i<10;i++)try{return new RandomAccessFile("\\\\.\\pipe\\discord-ipc-"+i,"rw");}catch(IOException ignored){}throw new IOException("Discord IPC unavailable");}
 private static void send(RandomAccessFile p,int opcode,JsonObject json)throws IOException{byte[] data=json.toString().getBytes(StandardCharsets.UTF_8);ByteBuffer b=ByteBuffer.allocate(8+data.length).order(ByteOrder.LITTLE_ENDIAN);b.putInt(opcode).putInt(data.length).put(data);p.write(b.array());}
 private static JsonObject read(RandomAccessFile p)throws IOException{for(int tries=0;tries<8;tries++){byte[] h=new byte[8];p.readFully(h);ByteBuffer b=ByteBuffer.wrap(h).order(ByteOrder.LITTLE_ENDIAN);int opcode=b.getInt(),n=b.getInt();if(n<0||n>65536||opcode==2)throw new IOException("Discord IPC frame");byte[] data=new byte[n];p.readFully(data);JsonObject json=JsonParser.parseString(new String(data,StandardCharsets.UTF_8)).getAsJsonObject();if(opcode==3){send(p,4,json);continue;}return json;}throw new IOException("Discord IPC responses");}
}
final class RpcSettingsScreen extends PrismSettingsScreen {
 RpcSettingsScreen(net.minecraft.client.gui.screen.Screen p){super(p,net.minecraft.text.Text.literal("Discord RPC"));}
 @Override protected void init(){super.init();flag("Показывать Interium в Discord","rpc.enabled",false);button("Application ID (не токен)",()->client.setScreen(new DeltaTextSettingScreen(this,"rpc.applicationId","Discord Application ID · только цифры")));button("Статус: "+DiscordPresence.status(),()->{});button("Без ника / IP сервера · только Windows IPC",()->{});}
}
